import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [goods, setGoods] = useState([]);
  const [search, setSearch] = useState('');
  const [filtered, setFiltered] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    fetch('http://localhost:5000/api/goods/getallgoods')
      .then((res) => {
        if (!res.ok) throw new Error('Network response was not ok');
        return res.json();
      })
      .then((data) => {
        setGoods(Array.isArray(data) ? data : []);
        setLoading(false);
      })
      .catch((err) => {
        setError(err.message || 'Fetch error');
        setLoading(false);
      });
  }, []);

  useEffect(() => {
    const q = search.trim().toLowerCase();
    if (!q) {
      setFiltered(goods);
      return;
    }
    const result = goods.filter((g) => {
      const name = (g.name || '').toString().toLowerCase();
      const brand = (g.brand || '').toString().toLowerCase();
      const category = (g.category || '').toString().toLowerCase();
      const itemid = (g.itemid || '').toString().toLowerCase();
      return (
        name.includes(q) ||
        brand.includes(q) ||
        category.includes(q) ||
        itemid.includes(q)
      );
    });
    setFiltered(result);
  }, [search, goods]);

  return (
    <div className="amazon-container">
      <nav className="navbar">
        <div className="logo">MyShop</div>
        <div className="search-wrap">
          <input
            type="text"
            className="search-box"
            placeholder="Search for goods by name, brand, category or id..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </nav>

      <main className="content">
        {loading ? (
          <div className="info">Loading goods...</div>
        ) : error ? (
          <div className="error">Error: {error}</div>
        ) : filtered.length === 0 ? (
          <div className="info">No goods found.</div>
        ) : (
          <div className="goods-grid">
            {filtered.map((good) => (
              <div key={good._id || good.itemid} className="good-card">
                <div className="good-image-wrap">
                  {good.imageUrl && good.imageUrl.length > 0 ? (
                    <img
                      src={good.imageUrl[0]}
                      alt={good.name}
                      className="good-image"
                    />
                  ) : (
                    <div className="image-placeholder">No image</div>
                  )}
                </div>
                <div className="good-info">
                  <div className="good-name">{good.name}</div>
                  <div className="good-brand">{good.brand}</div>
                  <div className="good-category">{good.category}</div>
                  <div className="good-price">${good.price?.toFixed(2)}</div>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
